(lib.mcBg0 = function(mode,startPosition,loop,reversed) {
if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		this.stop();
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

	// mcItemRail
	this.mcItemRail = new lib.Item3_Rail();
	this.mcItemRail.name = "mcItemRail";
	this.mcItemRail.setTransform(70.5,33.5,1,1,0,0,0,70.5,33.5);

	this.timeline.addTween(cjs.Tween.get(this.mcItemRail).wait(1));

	// img
	this.instance = new lib.AM3_Sea_type_imgs9();
	this.instance.setTransform(0,555.5,2,2);

	this.timeline.addTween(cjs.Tween.get(this.instance).wait(1));

	this._renderFirstFrame();

}).prototype = getMCSymbolPrototype(lib.mcBg0, new cjs.Rectangle(0,555.5,2560,234), null);


